// /frontend-react/src/components/ProfilePage.js (FINALIZED CLEAN CSS)

import React from 'react';
import HeaderBar from './HeaderBar';

// --- Local Mock Profile Data (Extracted from IC/Login) ---
const mockProfileData = {
    name: "LIM CHIN WEI",
    icNumber: "851020-07-5XXX",
    dateOfBirth: "20 / OCTOBER / 1985",
    address: "NO. 12, JALAN SAGA, KUALA LUMPUR",
    emergencyContact: "CHIN YEE (012-3456789)",
};

function ProfilePage({ isEasyMode, goToPage, onMenuClick }) {
    
    const profile = mockProfileData;

    // --- REVISED InfoCard Component for Clean Look ---
    const InfoCard = ({ title, value }) => (
        <div style={{
            padding: '20px', // Increased padding for space
            margin: '15px 0', // Increased vertical margin between cards
            width: '100%',
            backgroundColor: '#fff',
            borderBottom: '1px solid #ddd', // Subtle separator line instead of thick border
            borderRadius: '0', // No rounding needed for stacked layout
            textAlign: 'left',
            boxShadow: '0 1px 3px rgba(0,0,0,0.05)', // Very light shadow
        }}>
            {/* Title (Label) - Smaller, muted for hierarchy */}
            <p style={{ 
                fontSize: isEasyMode ? '20px' : '15px', 
                fontWeight: '600', 
                margin: '0 0 5px 0', 
                color: '#6c757d' // Muted gray color
            }}>
                {title.toUpperCase()}
            </p>
            
            {/* Value (Actual Data) - Large and prominent */}
            <p style={{ 
                fontSize: isEasyMode ? '34px' : '22px', // Larger font for key data
                fontWeight: 'bold',
                margin: 0, 
                color: '#333' 
            }}>
                {value}
            </p>
        </div>
    );
    // --- END REVISED InfoCard ---

    return (
        <div style={{ padding: '0 0 20px 0', textAlign: 'center' }}>
            <HeaderBar
                title="Profile"
                onBackClick={() => goToPage('dashboard')}
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '20px 0 10px 0', color: '#333' }}>
                Personal Details
            </h2>

            {/* Container for InfoCards - Uses full width, padding applied globally */}
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%' }}>
                {/* Note: InfoCards now use 100% width and rely on the container's max width */}
                <InfoCard title="Name" value={profile.name} isEasyMode={isEasyMode}/>
                <InfoCard title="IC Number" value={profile.icNumber} isEasyMode={isEasyMode}/>
                <InfoCard title="Date of Birth" value={profile.dateOfBirth} isEasyMode={isEasyMode}/>
                <InfoCard title="Address" value={profile.address} isEasyMode={isEasyMode}/>
                <InfoCard title="Emergency Contact" value={profile.emergencyContact} isEasyMode={isEasyMode}/>

                <button
                    onClick={() => alert("Redirecting to Edit Profile.")}
                    style={{
                        padding: '15px 30px',
                        fontSize: isEasyMode ? '28px' : '18px',
                        backgroundColor: 'orange',
                        color: 'white',
                        border: 'none',
                        borderRadius: '8px',
                        marginTop: '40px' // Increased spacing
                    }}
                >
                    EDIT PROFILE ✍️
                </button>
            </div>
        </div>
    );
}

export default ProfilePage;
